            <Link to="/estatisticas" onClick={() => setIsMobileMenuOpen(false)} className="px-4 py-3 bg-[#eef2ff] border border-blue-100 text-[#0f2851] rounded-xl text-sm font-bold">
              Estat├¡sticas
            </Link>

            <div className="font-bold text-[#0f2851] px-4 py-2 mt-2">Relat├│rios</div>
            <Link to="/relatorio-conteudos" onClick={() => setIsMobileMenuOpen(false)} className="px-4 py-2 text-sm text-slate-600 hover:bg-slate-50 rounded-xl ml-4">Conte├║dos</Link>
            <Link to="/relatorio-frequencia" onClick={() => setIsMobileMenuOpen(false)} className="px-4 py-2 text-sm text-slate-600 hover:bg-slate-50 rounded-xl ml-4">Frequ├¬ncias</Link>
            <Link to="/relatorio-medias" onClick={() => setIsMobileMenuOpen(false)} className="px-4 py-2 text-sm text-slate-600 hover:bg-slate-50 rounded-xl ml-4">M├®dias</Link>
            <Link to="/relatorio-notas" onClick={() => setIsMobileMenuOpen(false)} className="px-4 py-2 text-sm text-slate-600 hover:bg-slate-50 rounded-xl ml-4">Notas</Link>

            {user?.role !== 'ADMIN' && (
              <button onClick={() => { setIsMobileMenuOpen(false); setIsScheduleModalOpen(true); }} className="mt-4 px-4 py-3 bg-[#eef2ff] border border-blue-100 text-[#0f2851] rounded-xl text-sm font-bold text-left">
                Meus Hor├írios
              </button>
            )}
