import { X, User, Calendar, CreditCard, Users, Phone, MapPin, Activity, Building2, BookOpen } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useToast } from './common/Toast';
import { validarCPF } from '../utils/cpfUtils';

interface NovoAlunoModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (aluno: any) => void;
  alunoParaEditar?: any;
  fixedEscolaId?: string;
}

export default function NovoAlunoModal({ isOpen, onClose, onSave, alunoParaEditar, fixedEscolaId }: NovoAlunoModalProps) {
  const { showError } = useToast();
  const [escolas, setEscolas] = useState<any[]>([]);
  const [turmas, setTurmas] = useState<any[]>([]);
  const [loadingEscolas, setLoadingEscolas] = useState(false);
  const [loadingTurmas, setLoadingTurmas] = useState(false);

  const [formData, setFormData] = useState({
    escola_id: '',
    turma_id: '',
    nome: '',
    dataNascimento: '',
    cpf: '',
    sexo: '',
    nomeResponsavel: '',
    telefone: '',
    endereco: '',
    status: 'Ativo',
  });

  const fetchEscolas = React.useCallback(async () => {
    setLoadingEscolas(true);
    const { data } = await supabase.from('escolas').select('id, nome').eq('status', 'Ativa').order('nome');
    if (data) setEscolas(data);
    setLoadingEscolas(false);
  }, []);

  /* eslint-disable react-hooks/set-state-in-effect */
  useEffect(() => {
    if (isOpen) {
      fetchEscolas();
    }
  }, [isOpen, fetchEscolas]);
  /* eslint-enable react-hooks/set-state-in-effect */

  const fetchTurmas = React.useCallback(async (escolaId: string) => {
    setLoadingTurmas(true);
    const { data } = await supabase.from('turmas').select('id, nome, turno').eq('escola_id', escolaId).order('nome');
    if (data) setTurmas(data);
    setLoadingTurmas(false);
  }, []);

  /* eslint-disable react-hooks/set-state-in-effect */
  useEffect(() => {
    if (formData.escola_id) {
      fetchTurmas(formData.escola_id);
    } else {
      setTurmas([]);
    }
  }, [formData.escola_id, fetchTurmas]);
  /* eslint-enable react-hooks/set-state-in-effect */

  /* eslint-disable react-hooks/set-state-in-effect */
  useEffect(() => {
    if (alunoParaEditar) {
      setFormData({
        escola_id: alunoParaEditar.escola_id || '',
        turma_id: alunoParaEditar.turma_id || '',
        nome: alunoParaEditar.nome || '',
        dataNascimento: alunoParaEditar.dataNascimento || alunoParaEditar.data_nascimento || '',
        cpf: alunoParaEditar.cpf || '',
        sexo: alunoParaEditar.sexo || '',
        nomeResponsavel: alunoParaEditar.nomeResponsavel || alunoParaEditar.nome_responsavel || '',
        telefone: alunoParaEditar.telefone || '',
        endereco: alunoParaEditar.endereco || '',
        status: alunoParaEditar.status || 'Ativo',
      });
    } else {
      setFormData({
        escola_id: fixedEscolaId || (escolas.length === 1 ? escolas[0].id : ''),
        turma_id: '',
        nome: '',
        dataNascimento: '',
        cpf: '',
        sexo: '',
        nomeResponsavel: '',
        telefone: '',
        endereco: '',
        status: 'Ativo',
      });
    }
  }, [alunoParaEditar, isOpen, escolas, fixedEscolaId]);
  /* eslint-enable react-hooks/set-state-in-effect */

  const formatCPF = (value: string) => {
    return value
      .replace(/\D/g, '')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d{1,2})/, '$1-$2')
      .replace(/(-\d{2})\d+?$/, '$1');
  };

  const formatTelefone = (value: string) => {
    return value
      .replace(/\D/g, '')
      .replace(/(\d{2})(\d)/, '($1) $2')
      .replace(/(\d{5})(\d)/, '$1-$2')
      .replace(/(-\d{4})\d+?$/, '$1');
  };

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // BUG-01 FIX: substituir alert() bloqueante por Toast
    if (!formData.escola_id) {
      showError('Selecione uma Escola antes de continuar.');
      return;
    }
    if (!formData.turma_id) {
      showError('Selecione uma Turma antes de continuar.');
      return;
    }
    // Validar CPF apenas se foi alterado (para n├úo bloquear edi├º├úo de outros campos com CPF legado)
    const cpfOriginal = alunoParaEditar?.cpf || '';
    const cpfFoiAlterado = formData.cpf !== cpfOriginal;
    if (formData.cpf && cpfFoiAlterado && !validarCPF(formData.cpf)) {
      showError('CPF inv├ílido. Verifique os d├¡gitos e tente novamente.');
      return;
    }
    onSave({
      ...formData,
      data_nascimento: formData.dataNascimento,
      nome_responsavel: formData.nomeResponsavel
    });
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl flex flex-col animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-hidden">
        <div className="flex items-center justify-between p-6 border-b border-slate-200 sticky top-0 bg-white z-10 shrink-0">
          <h2 className="text-xl font-bold text-slate-800">
            {alunoParaEditar ? 'Editar Aluno' : 'Novo Aluno'}
          </h2>
          <button
            type="button"
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="overflow-y-auto p-6">
          <form id="aluno-form" onSubmit={handleSubmit} className="space-y-6">

            <div className="grid grid-cols-2 gap-4 bg-slate-50 p-4 rounded-xl border border-slate-100">
              <div className="space-y-1.5">
                <label className="text-sm font-semibold text-slate-700 flex items-center gap-2">
                  <Building2 className="w-4 h-4 text-blue-600" />
                  Escola a qual pertence
                </label>
                <select
                  required
                  disabled={loadingEscolas}
                  value={formData.escola_id}
                  onChange={(e) => setFormData({ ...formData, escola_id: e.target.value, turma_id: '' })}
                  className="w-full px-4 py-2.5 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-600/20 focus:border-blue-600 transition-all bg-white font-medium"
                >
                  <option value="" disabled>Selecione a Escola</option>
                  {escolas.map(escola => (
                    <option key={escola.id} value={escola.id}>{escola.nome}</option>
                  ))}
                </select>
              </div>

              <div className="space-y-1.5">
                <label className="text-sm font-semibold text-slate-700 flex items-center gap-2">
                  <BookOpen className="w-4 h-4 text-blue-600" />
                  Turma Destinada
                </label>
                <select
                  required
                  disabled={!formData.escola_id || loadingTurmas}
                  value={formData.turma_id}
                  onChange={(e) => setFormData({ ...formData, turma_id: e.target.value })}
                  className="w-full px-4 py-2.5 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-600/20 focus:border-blue-600 transition-all bg-white font-medium"
                >
                  <option value="" disabled>Selecione uma Escola antes</option>
                  {turmas.map(turma => (
                    <option key={turma.id} value={turma.id}>{turma.nome} ({turma.turno})</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="space-y-1.5 pt-2">
              <label className="text-sm font-medium text-slate-700 flex items-center gap-2">
                <User className="w-4 h-4 text-slate-400" />
                Nome Completo do Aluno
              </label>
              <input
                type="text"
                required
                value={formData.nome}
                onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
                className="w-full px-4 py-2.5 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-600/20 focus:border-blue-600 transition-all"
                placeholder="Ex: Ana Maria Santos"
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="text-sm font-medium text-slate-700 flex items-center gap-2">
                  <Calendar className="w-4 h-4 text-slate-400" />
                  Data de Nascimento
                </label>
                <input
                  type="date"
                  required
                  value={formData.dataNascimento}
                  onChange={(e) => setFormData({ ...formData, dataNascimento: e.target.value })}
                  className="w-full px-4 py-2.5 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-600/20 focus:border-blue-600 transition-all text-slate-700"
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-sm font-medium text-slate-700 flex items-center gap-2">
                  <CreditCard className="w-4 h-4 text-slate-400" />
                  CPF <span className="text-xs text-slate-400 font-normal">(Opcional)</span>
                </label>
                <input
                  type="text"
                  maxLength={14}
                  value={formData.cpf}
                  onChange={(e) => setFormData({ ...formData, cpf: formatCPF(e.target.value) })}
                  className="w-full px-4 py-2.5 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-600/20 focus:border-blue-600 transition-all"
                  placeholder="000.000.000-00"
                />
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700 flex items-center gap-2 pb-1">
                <Users className="w-4 h-4 text-slate-400" />
                Sexo <span className="text-xs text-slate-400 font-normal">(Opcional)</span>
              </label>
              <select
                value={formData.sexo}
                onChange={(e) => setFormData({ ...formData, sexo: e.target.value })}
                className="w-full px-4 py-2.5 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-600/20 focus:border-blue-600 transition-all bg-white text-slate-700"
              >
                <option value="">Selecione...</option>
                <option value="Feminino">Feminino</option>
                <option value="Masculino">Masculino</option>
                <option value="Outro">Outro</option>
                <option value="Prefiro n├úo informar">Prefiro n├úo informar</option>
              </select>
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700 flex items-center gap-2 pb-1">
                <Activity className="w-4 h-4 text-slate-400" />
                Status da Matr├¡cula
              </label>
              <div className="flex gap-4">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="status_aluno"
                    checked={formData.status === 'Ativo'}
                    onChange={() => setFormData({ ...formData, status: 'Ativo' })}
                    className="text-blue-600 focus:ring-blue-600"
                  />
                  <span className="text-sm text-slate-700">Ativo</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="status_aluno"
                    checked={formData.status === 'Inativo'}
                    onChange={() => setFormData({ ...formData, status: 'Inativo' })}
                    className="text-blue-600 focus:ring-blue-600"
                  />
                  <span className="text-sm text-slate-700">Inativo</span>
                </label>
              </div>
            </div>

            <div className="space-y-1.5 pt-4 border-t border-slate-100">
              <h3 className="text-sm font-semibold text-slate-800 mb-3">Informa├º├Áes de Contato / Filia├º├úo</h3>
              <div className="space-y-4">
                <div className="space-y-1.5">
                  <label className="text-sm font-medium text-slate-700 flex items-center gap-2">
                    <User className="w-4 h-4 text-slate-400" />
                    Nome do Respons├ível
                  </label>
                  <input
                    type="text"
                    required
                    value={formData.nomeResponsavel}
                    onChange={(e) => setFormData({ ...formData, nomeResponsavel: e.target.value })}
                    className="w-full px-4 py-2.5 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-600/20 focus:border-blue-600 transition-all"
                    placeholder="Ex: Carlos Silva"
                  />
                </div>

                <div className="space-y-1.5">
                  <label className="text-sm font-medium text-slate-700 flex items-center gap-2">
                    <Phone className="w-4 h-4 text-slate-400" />
                    Telefone
                  </label>
                  <input
                    type="tel"
                    required
                    maxLength={15}
                    value={formData.telefone}
                    onChange={(e) => setFormData({ ...formData, telefone: formatTelefone(e.target.value) })}
                    className="w-full px-4 py-2.5 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-600/20 focus:border-blue-600 transition-all"
                    placeholder="(00) 00000-0000"
                  />
                </div>

                <div className="space-y-1.5">
                  <label className="text-sm font-medium text-slate-700 flex items-center gap-2">
                    <MapPin className="w-4 h-4 text-slate-400" />
                    Endere├ºo Completo
                  </label>
                  <input
                    type="text"
                    required
                    value={formData.endereco}
                    onChange={(e) => setFormData({ ...formData, endereco: e.target.value })}
                    className="w-full px-4 py-2.5 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-600/20 focus:border-blue-600 transition-all"
                    placeholder="Rua, N├║mero, Bairro, Cidade"
                  />
                </div>
              </div>
            </div>
          </form>
        </div>

        <div className="flex justify-end gap-3 p-6 border-t border-slate-200 bg-slate-50 sticky bottom-0 z-10 shrink-0">
          <button
            type="button"
            onClick={onClose}
            className="px-5 py-2.5 text-sm font-medium text-slate-600 hover:text-slate-800 hover:bg-slate-200 rounded-lg transition-colors"
          >
            Cancelar
          </button>
          <button
            type="submit"
            form="aluno-form"
            className="px-5 py-2.5 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg transition-colors shadow-sm"
          >
            {alunoParaEditar ? 'Salvar Altera├º├Áes' : 'Salvar Aluno'}
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { X, User, Mail, CreditCard, Phone, Activity, Briefcase, GraduationCap, LayoutGrid, KeyRound, Plus } from 'lucide-react';

interface NovoProfessorModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (professor: any) => void;
  professorParaEditar?: any;
}

const DEPARTAMENTOS = ['Geral', 'BIOL├ôGICAS', 'HUMANAS', 'EXATAS', 'LINGUAGENS'];
const DISCIPLINAS = [
  'Portugu├¬s', 'Matem├ítica', 'Ci├¬ncias', 'Hist├│ria', 'Geografia',
  'Artes', 'Educa├º├úo F├¡sica', 'Ingl├¬s', 'Ensino Religioso'
];

export default function NovoProfessorModal({ isOpen, onClose, onSave, professorParaEditar }: NovoProfessorModalProps) {
  const [formData, setFormData] = useState({
    nome: '',
    email: '',
    cpf: '',
    telefone: '',
    senha: '',
    status: 'Ativo',
    vinculo: 'Efetivo',
    departamento: 'Geral',
    disciplinas: [] as string[]
  });

  const [novaDisciplina, setNovaDisciplina] = useState('');
  const [showNovaDisciplina, setShowNovaDisciplina] = useState(false);

  const handleAddCustomDisciplina = () => {
    if (novaDisciplina.trim() && !formData.disciplinas.includes(novaDisciplina.trim())) {
      setFormData(prev => ({
        ...prev,
        disciplinas: [...prev.disciplinas, novaDisciplina.trim()]
      }));
      setNovaDisciplina('');
      setShowNovaDisciplina(false);
    }
  };

  /* eslint-disable react-hooks/set-state-in-effect */
  useEffect(() => {
    if (professorParaEditar) {
      setFormData({
        nome: professorParaEditar.nome || '',
        email: professorParaEditar.email || '',
        cpf: professorParaEditar.cpf || '',
        telefone: professorParaEditar.telefone || '',
        senha: '',
        status: professorParaEditar.status || 'Ativo',
        vinculo: professorParaEditar.vinculo || 'Efetivo',
        departamento: professorParaEditar.departamento || 'Geral',
        disciplinas: professorParaEditar.disciplinas || []
      });
    } else {
      setFormData({
        nome: '',
        email: '',
        cpf: '',
        telefone: '',
        senha: '',
        status: 'Ativo',
        vinculo: 'Efetivo',
        departamento: 'Geral',
        disciplinas: []
      });
    }
  }, [professorParaEditar, isOpen]);
  /* eslint-enable react-hooks/set-state-in-effect */

  const toggleDisciplina = (disc: string) => {
    setFormData(prev => ({
      ...prev,
      disciplinas: prev.disciplinas.includes(disc)
        ? prev.disciplinas.filter(d => d !== disc)
        : [...prev.disciplinas, disc]
    }));
  };

  const formatCPF = (value: string) => {
    return value
      .replace(/\D/g, '')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d{1,2})/, '$1-$2')
      .replace(/(-\d{2})\d+?$/, '$1');
  };

  const formatTelefone = (value: string) => {
    return value
      .replace(/\D/g, '')
      .replace(/(\d{2})(\d)/, '($1) $2')
      .replace(/(\d{5})(\d)/, '$1-$2')
      .replace(/(-\d{4})\d+?$/, '$1');
  };

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(formData);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl flex flex-col animate-in zoom-in-95 duration-200 max-h-[95vh] overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-slate-100 bg-white z-10">
          <h2 className="text-xl font-bold text-slate-800">
            {professorParaEditar ? 'Editar Professor' : 'Novo Professor'}
          </h2>
          <button
            type="button"
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto overflow-x-hidden p-6 custom-scrollbar">
          <form id="professor-form" onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Nome */}
              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                  <User className="w-4 h-4 text-slate-400" />
                  Nome Completo
                </label>
                <input
                  type="text"
                  required
                  value={formData.nome}
                  onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-600/10 focus:border-blue-600 transition-all placeholder-slate-400 font-medium"
                  placeholder="Ex: Jo├úo da Silva"
                />
              </div>

              {/* Email */}
              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                  <Mail className="w-4 h-4 text-slate-400" />
                  E-mail
                </label>
                <input
                  type="email"
                  required
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-600/10 focus:border-blue-600 transition-all placeholder-slate-400 font-medium"
                  placeholder="Ex: joao.silva@escola.com"
                />
              </div>

              {/* CPF */}
              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                  <CreditCard className="w-4 h-4 text-slate-400" />
                  CPF
                </label>
                <input
                  type="text"
                  required
                  maxLength={14}
                  value={formData.cpf}
                  onChange={(e) => setFormData({ ...formData, cpf: formatCPF(e.target.value) })}
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-600/10 focus:border-blue-600 transition-all placeholder-slate-400 font-medium"
                  placeholder="000.000.000-00"
                />
              </div>

              {/* Telefone */}
              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                  <Phone className="w-4 h-4 text-slate-400" />
                  Telefone
                </label>
                <input
                  type="tel"
                  required
                  maxLength={15}
                  value={formData.telefone}
                  onChange={(e) => setFormData({ ...formData, telefone: formatTelefone(e.target.value) })}
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-600/10 focus:border-blue-600 transition-all placeholder-slate-400 font-medium"
                  placeholder="(00) 00000-0000"
                />
              </div>

              {/* Senha de Acesso (s├│ no cadastro novo) */}
              {!professorParaEditar && (
                <div className="space-y-2 md:col-span-2">
                  <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                    <KeyRound className="w-4 h-4 text-slate-400" />
                    Senha de Acesso
                  </label>
                  <input
                    type="password"
                    value={formData.senha}
                    onChange={(e) => setFormData({ ...formData, senha: e.target.value })}
                    className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-600/10 focus:border-blue-600 transition-all placeholder-slate-400 font-medium"
                    placeholder="Padr├úo: @prof123 (M├¡n. 6 caracteres)"
                  />
                  <p className="text-[10px] text-slate-400 font-medium ml-1">
                    Defina uma senha para que o professor possa acessar o sistema. Se deixar vazio, usar├í a senha padr├úo @prof123.
                  </p>
                </div>
              )}

              {/* V├¡nculo */}
              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                  <Briefcase className="w-4 h-4 text-slate-400" />
                  V├¡nculo
                </label>
                <select
                  required
