source:
import React, { useState, useEffect } from 'react';
import { Loader2, Check, X } from 'lucide-react';
import { useTurma, Avaliacao, Aluno } from '../../contexts/TurmaContext';
import { APP_CONFIG } from '../../config/appConfig';
import { useCaptcha } from '../../hooks/useCaptcha';
import { getBimestrePorData, formatarDataParaISO } from '../../utils/dateUtils';

// Sub-componentes
import AvaliacoesList from './avaliacoes/AvaliacoesList';
import AvaliacaoForm from './avaliacoes/AvaliacaoForm';
import AvaliacaoDetailsView from './avaliacoes/AvaliacaoDetailsView';
import NotasEditor from './avaliacoes/NotasEditor';
import SegundaChamadaEditor from './avaliacoes/SegundaChamadaEditor';
import DeleteAvaliacaoModal from './avaliacoes/DeleteAvaliacaoModal';

interface AvaliacoesTabProps {
  disabled?: boolean;
}

export default function AvaliacoesTab({ disabled }: AvaliacoesTabProps) {
  const { 
    turmaAtiva, alunos, avaliacoes, conteudos, loading, 
    salvarAvaliacao, removerAvaliacao, salvarNotas, 
    carregarFaltasDaData, faltasPorData 
  } = useTurma();

  const [avaliacaoViewMode, setAvaliacaoViewMode] = useState<'list' | 'details' | 'edit' | 'grades' | 'second_call'>('list');
  const [selectedAvaliacao, setSelectedAvaliacao] = useState<any>(null);
  const [selectedDate, setSelectedDate] = useState<string>('');
  const [isDatePickerOpen, setIsDatePickerOpen] = useState(false);
  const [instrumentoAvaliacao, setInstrumentoAvaliacao] = useState('AVALIACAO ESCRITA');
  const [objetosAvaliacao, setObjetosAvaliacao] = useState<any[]>([]);
  const [periodoLetivo, setPeriodoLetivo] = useState('');
  const [unidadeDidatica, setUnidadeDidatica] = useState('');
  const [objetoConhecimento, setObjetoConhecimento] = useState('');
  const [valorMaximo, setValorMaximo] = useState('10,00');
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [avaliacaoToDelete, setAvaliacaoToDelete] = useState<any>(null);
  const [localNotas, setLocalNotas] = useState<Record<string, string>>({});
  const [calendarMonth, setCalendarMonth] = useState(new Date().getMonth());
  const [calendarYear, setCalendarYear] = useState(new Date().getFullYear());
  const [isSaving, setIsSaving] = useState(false);
  const [secondCallRows, setSecondCallRows] = useState<Record<string, { selected: boolean, date: string, grade: string }>>({});

  const PERIODOS_LABELS: Record<string, string> = {};
  APP_CONFIG.PERIODOS.filter(p => p.id.includes('BIMESTRE')).forEach(b => {
    // Formata a exibi├º├úo como: "1. BIMESTRE 05/02/2026 - 23/04/2026"
    const start = new Date(b.dataInicio).toLocaleDateString('pt-BR');
    const end = new Date(b.dataFim).toLocaleDateString('pt-BR');
    PERIODOS_LABELS[b.nome] = `${b.label} ${start} - ${end}`;
  });

  const {
    generatedCaptcha,
    captchaInput,
    setCaptchaInput,
    captchaError,
    generateNewCaptcha,
    validateCaptcha
  } = useCaptcha();

  // Memos para op├º├Áes de objetos de conhecimento
  const unidadesOpcoes = React.useMemo(() => {
    if (!selectedDate || !conteudos) return [];
    const bimestreAtual = getBimestrePorData(selectedDate);
    const unidades = conteudos
      .filter(c => getBimestrePorData(c.data) === bimestreAtual)
      .map(c => c.habilidades[0])
      .filter((u, index, self) => u && self.indexOf(u) === index);
    return unidades;
  }, [selectedDate, conteudos]);

  const objetosOpcoes = React.useMemo(() => {
    if (!unidadeDidatica || !conteudos) return [];
    const objetos = conteudos
      .filter(c => c.habilidades[0] === unidadeDidatica)
      .flatMap(c => c.objetos)
      .filter((o, index, self) => o && self.indexOf(o) === index);
    return objetos;
  }, [unidadeDidatica, conteudos]);

  // Alunos filtrados para notas (l├│gica de RP)
  const alunosParaNotas = React.useMemo(() => {
    if (!selectedAvaliacao) return [];
    if (selectedAvaliacao.parent_id) {
      return alunos.filter(aluno => {
        const notaPai = parseFloat((aluno.notas?.[selectedAvaliacao.parent_id] || '0').replace(',', '.'));
        return notaPai < 6.0;
      });
    }
    return alunos;
  }, [selectedAvaliacao, alunos]);

  // Carregar notas ao entrar em modo editor
  /* eslint-disable react-hooks/set-state-in-effect */
  useEffect(() => {
    if (avaliacaoViewMode === 'grades' && selectedAvaliacao) {
      const notasMap: Record<string, string> = {};
      alunosParaNotas.forEach(aluno => {
        notasMap[aluno.id] = aluno.notas?.[selectedAvaliacao.id] || '';
      });
      setLocalNotas(notasMap);
    }
  }, [avaliacaoViewMode, selectedAvaliacao, alunosParaNotas]);
  /* eslint-enable react-hooks/set-state-in-effect */

  // Atualizar per├¡odo letivo pela data selecionada
  /* eslint-disable react-hooks/set-state-in-effect */
  useEffect(() => {
    if (selectedDate) {
      const bim = getBimestrePorData(selectedDate);
      setPeriodoLetivo(bim);
      setUnidadeDidatica('');
      setObjetoConhecimento('');
    }
  }, [selectedDate]);
  /* eslint-enable react-hooks/set-state-in-effect */

  // Handlers
  const resetForm = () => {
    setSelectedDate('');
    setObjetosAvaliacao([]);
    setSelectedAvaliacao(null);
    setCaptchaInput('');
    setPeriodoLetivo('');
    setUnidadeDidatica('');
    setObjetoConhecimento('');
    setValorMaximo('10,00');
    generateNewCaptcha();
  };

  const handleSaveAvaliacao = async () => {
    if (!validateCaptcha()) { alert('C├│digo incorreto!'); return; }
    if (!selectedDate) { alert('Selecione uma data!'); return; }
    if (objetosAvaliacao.length === 0) { alert('Adicione pelo menos um Objeto de Conhecimento!'); return; }

    const payload: Avaliacao = {
      id: selectedAvaliacao ? selectedAvaliacao.id : `temp_${Date.now()}`,
      turmaId: turmaAtiva?.id || '',
      tipo: selectedAvaliacao?.tipo || `AV${String(avaliacoes.filter(a => !a.parent_id).length + 1).padStart(2, '0')}`,
      data: selectedDate,
      instrumento: instrumentoAvaliacao,
      objetos: objetosAvaliacao,
      bimestre: getBimestrePorData(selectedDate),
      valorMaximo: parseFloat(valorMaximo.replace(',', '.')) || 10,
      parent_id: selectedAvaliacao?.parent_id
    };

    await salvarAvaliacao(payload);
    setAvaliacaoViewMode('list');
    resetForm();
  };

  const handleConfirmGrades = async () => {
    if (!validateCaptcha()) { alert('C├│digo incorreto!'); return; }
    if (!selectedAvaliacao) return;

    const notasToSave = Object.entries(localNotas)
      .filter(([_, val]) => val !== '')
      .map(([alunoId, valor]) => ({ alunoId, valor }));

    await salvarNotas(selectedAvaliacao.id, notasToSave);
    setAvaliacaoViewMode('list');
    resetForm();
  };

  const handleSaveSecondCall = async () => {
    if (!validateCaptcha()) { alert('C├│digo incorreto!'); return; }
    if (!selectedAvaliacao) return;

    const selectedAlunIds = Object.keys(secondCallRows).filter(id => secondCallRows[id].selected);
    if (selectedAlunIds.length === 0) { alert('Selecione pelo menos um aluno!'); return; }

    setIsSaving(true);
    const dates = [...new Set(selectedAlunIds.map(id => secondCallRows[id].date))];

    for (const d of dates) {
      const payload: Avaliacao = {
        id: `temp_2ch_${Date.now()}_${d}`,
        turmaId: selectedAvaliacao.turmaId,
        tipo: `2CH`,
        data: d,
        instrumento: selectedAvaliacao.instrumento,
        objetos: selectedAvaliacao.objetos,
        bimestre: selectedAvaliacao.bimestre,
        valorMaximo: selectedAvaliacao.valorMaximo || 10,
        parent_id: selectedAvaliacao.id
      };

      const createdId = await salvarAvaliacao(payload);
      const notasParaData = selectedAlunIds
        .filter(id => secondCallRows[id].date === d)
        .map(id => ({ alunoId: id, valor: secondCallRows[id].grade }));

      await salvarNotas(createdId, notasParaData);
    }

    setAvaliacaoViewMode('list');
    setIsSaving(false);
  };

  const handleNotaChange = (alunoId: string, val: string) => {
    const numStr = val.replace(/\D/g, '');
    if (!numStr) { setLocalNotas(prev => ({ ...prev, [alunoId]: '' })); return; }
    const numVal = parseInt(numStr, 10);
    if (numVal > 1000) return;
    const formatted = (numVal / 100).toFixed(2).replace('.', ',');
    setLocalNotas(prev => ({ ...prev, [alunoId]: formatted }));
  };

  if (loading) {
    return (
      <div className="py-20 flex flex-col items-center justify-center text-slate-400">
        <Loader2 className="w-10 h-10 animate-spin mb-4" />
        <p className="font-medium">Carregando dados da turma...</p>
      </div>
    );
  }

  return (
    <div className="animate-in fade-in slide-in-from-top-4 duration-300">

      {avaliacaoViewMode === 'list' && (
        <AvaliacoesList 
          avaliacoes={avaliacoes}
          alunos={alunos}
          faltasPorData={faltasPorData}
          onViewDetails={(av) => { setSelectedAvaliacao(av); setAvaliacaoViewMode('details'); }}
          onEdit={(av) => { 
            setSelectedAvaliacao(av); 
            setSelectedDate(av.data); 
            setInstrumentoAvaliacao(av.instrumento || 'AVALIACAO ESCRITA'); 
            setObjetosAvaliacao(av.objetos || []); 
            setValorMaximo(av.valorMaximo ? av.valorMaximo.toString().replace('.', ',') : '10,00');
            setAvaliacaoViewMode('edit'); 
          }}
          onDelete={(av) => { setAvaliacaoToDelete(av); setShowDeleteModal(true); }}
          onAddRP={(av) => {
            const novoRP: any = {
              turmaId: av.turmaId,
              tipo: av.tipo.includes('AV') ? av.tipo.replace('AV', 'RP') : `RP - ${av.tipo}`,
              data: new Date().toISOString().split('T')[0],
              instrumento: av.instrumento,
              objetos: av.objetos,
              bimestre: av.bimestre,
              valorMaximo: av.valorMaximo || 10,
              parent_id: av.id
            };
            setSelectedAvaliacao(novoRP);
            setSelectedDate(novoRP.data);
            setInstrumentoAvaliacao(novoRP.instrumento);
            setObjetosAvaliacao(novoRP.objetos);
            setValorMaximo(novoRP.valorMaximo ? novoRP.valorMaximo.toString().replace('.', ',') : '10,00');
            setAvaliacaoViewMode('edit');
          }}
          onShowGrades={(av) => { setSelectedAvaliacao(av); setAvaliacaoViewMode('grades'); }}
          onSecondCall={(av) => {
            setSelectedAvaliacao(av);
            const rows: any = {};
            alunos.forEach(a => {
              rows[a.id] = { selected: !a.notas?.[av.id], date: new Date().toISOString().split('T')[0], grade: '' };
            });
            setSecondCallRows(rows);
            setAvaliacaoViewMode('second_call');
            generateNewCaptcha();
          }}
          onAddAvaliacao={() => { resetForm(); setAvaliacaoViewMode('edit'); }}
          disabled={disabled}
        />
      )}

      {avaliacaoViewMode === 'edit' && (
        <AvaliacaoForm 
          selectedAvaliacao={selectedAvaliacao}
          selectedDate={selectedDate}
          instrumentoAvaliacao={instrumentoAvaliacao}
          objetosAvaliacao={objetosAvaliacao}
          periodoLetivo={periodoLetivo}
          unidadeDidatica={unidadeDidatica}
          objetoConhecimento={objetoConhecimento}
          valorMaximo={valorMaximo}
          unidadesOpcoes={unidadesOpcoes}
          objetosOpcoes={objetosOpcoes}
          generatedCaptcha={generatedCaptcha}
          captchaInput={captchaInput}
          captchaError={captchaError}
          isDatePickerOpen={isDatePickerOpen}
          calendarMonth={calendarMonth}
          calendarYear={calendarYear}
          PERIODOS_LABELS={PERIODOS_LABELS}
          onSave={handleSaveAvaliacao}
          onCancel={() => { setAvaliacaoViewMode('list'); resetForm(); }}
          onAddObjeto={() => {
            if (!unidadeDidatica || !objetoConhecimento) return alert('Selecione os campos!');
            if (objetosAvaliacao.some(o => o.unidade === unidadeDidatica && o.objeto === objetoConhecimento)) return alert('J├í existe!');
            setObjetosAvaliacao(prev => [...prev, { unidade: unidadeDidatica, objeto: objetoConhecimento }]);
          }}
          onRemoveObjeto={(idx) => setObjetosAvaliacao(prev => prev.filter((_, i) => i !== idx))}
          onSetSelectedDate={setSelectedDate}
          onSetIsDatePickerOpen={setIsDatePickerOpen}
          onSetInstrumentoAvaliacao={setInstrumentoAvaliacao}
          onSetPeriodoLetivo={setPeriodoLetivo}
          onSetUnidadeDidatica={setUnidadeDidatica}
          onSetObjetoConhecimento={setObjetoConhecimento}
          onSetValorMaximo={setValorMaximo}
          onSetCaptchaInput={setCaptchaInput}
          onGenerateNewCaptcha={generateNewCaptcha}
          onSetCalendarMonth={setCalendarMonth}
          onSetCalendarYear={setCalendarYear}
        />
      )}

      {avaliacaoViewMode === 'details' && (
        <AvaliacaoDetailsView 
          selectedAvaliacao={selectedAvaliacao}
          onBack={() => { setAvaliacaoViewMode('list'); setSelectedAvaliacao(null); }}
        />
      )}

      {avaliacaoViewMode === 'grades' && (
        <NotasEditor 
          selectedAvaliacao={selectedAvaliacao}
          alunosParaNotas={alunosParaNotas}
          localNotas={localNotas}
          faltasPorData={faltasPorData}
          generatedCaptcha={generatedCaptcha}
          captchaInput={captchaInput}
          captchaError={captchaError}
          onNotaChange={handleNotaChange}
          onConfirm={handleConfirmGrades}
          onCancel={() => { setAvaliacaoViewMode('list'); resetForm(); }}
          onSetCaptchaInput={setCaptchaInput}
          onGenerateNewCaptcha={generateNewCaptcha}
          disabled={disabled}
        />
      )}

      {avaliacaoViewMode === 'second_call' && (
        <SegundaChamadaEditor 
          selectedAvaliacao={selectedAvaliacao}
          alunos={alunos.filter(a => faltasPorData[formatarDataParaISO(selectedAvaliacao?.data || '')]?.has(a.id))}
          secondCallRows={secondCallRows}
          isSaving={isSaving}
          generatedCaptcha={generatedCaptcha}
          captchaInput={captchaInput}
          captchaError={captchaError}
          onSetSecondCallRows={setSecondCallRows}
          onSave={handleSaveSecondCall}
          onCancel={() => { setAvaliacaoViewMode('list'); resetForm(); }}
          onSetCaptchaInput={setCaptchaInput}
          onGenerateNewCaptcha={generateNewCaptcha}
        />
      )}

      {showDeleteModal && (
        <DeleteAvaliacaoModal 
          onConfirm={async () => {
            if (avaliacaoToDelete) await removerAvaliacao(avaliacaoToDelete.id);
            setShowDeleteModal(false);
            setAvaliacaoToDelete(null);
          }}
          onCancel={() => { setShowDeleteModal(false); setAvaliacaoToDelete(null); }}
        />
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Search, Check, Trash2, ArrowLeft } from 'lucide-react';
import Captcha from '../common/Captcha';
import { useTurma, Aluno } from '../../contexts/TurmaContext';
import { useCaptcha } from '../../hooks/useCaptcha';
import { useToast } from '../common/Toast';


interface FrequenciaTabProps {
  selectedDate: string;
  tempoAula: string;
  setTempoAula: (v: string) => void;
  disponiveisTempos: string[];
  disabled?: boolean;
}

export default function FrequenciaTab({
  selectedDate,
  tempoAula,
  setTempoAula,
  disponiveisTempos,
  disabled,
}: FrequenciaTabProps) {
  const { turmaAtiva, alunos, registrarLancamento, removerLancamento, salvarFrequencia, buscarFrequencia, removerFrequencia, lancamentos } = useTurma();
  const { showError: showToastError } = useToast();

  const [studentData, setStudentData] = useState<Aluno[]>([]);
  const [isLaunching, setIsLaunching] = useState(false);
  const [showDeleteFreqModal, setShowDeleteFreqModal] = useState(false);

  const isLancado = lancamentos.some(l => 
    l.data === selectedDate && 
    l.tempo === tempoAula && 
    l.tipo === 'frequencia'
  );

  const {
    generatedCaptcha,
    captchaInput,
    setCaptchaInput,
    captchaError,
    generateNewCaptcha,
    validateCaptcha
  } = useCaptcha();

  // Carregar frequ├¬ncia do banco quando a data ou o tempo mudar
  useEffect(() => {
    if (turmaAtiva && selectedDate && tempoAula) {
      buscarFrequencia(selectedDate, tempoAula);
    }
  }, [selectedDate, tempoAula, turmaAtiva, buscarFrequencia]);

  // Sincronizar o estado local com os alunos do contexto (que agora v├¬m do banco)
  /* eslint-disable react-hooks/set-state-in-effect */
  useEffect(() => {
    setStudentData(alunos.map(a => ({ ...a })));
  }, [alunos]);
  /* eslint-enable react-hooks/set-state-in-effect */

  const toggleFreq = (id: string) => {
    setStudentData(prev => prev.map(s => {
      if (s.id === id) {
        // Ciclo: P -> F -> FJ -> '' (Cinza) -> P
        const nextFreq = s.freq === 'P' ? 'F' : s.freq === 'F' ? 'FJ' : s.freq === 'FJ' ? '' : 'P';
        return { ...s, freq: nextFreq };
      }
      return s;
    }));
  };

  const togglePart = (id: string, part: string) => {
    setStudentData(prev => prev.map(s => s.id === id ? { ...s, part } : s));
  };

  const handleConfirm = async () => {
    if (validateCaptcha()) {
      if (turmaAtiva) {
        await salvarFrequencia(selectedDate, tempoAula, studentData);
        setIsLaunching(false);
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }
    } else {
      showToastError('C├│digo incorreto. Tente novamente.');
    }
  };

  const handleExcluirFrequencia = async () => {
    await removerFrequencia(selectedDate, tempoAula);
    generateNewCaptcha();
    setShowDeleteFreqModal(false);
    setIsLaunching(false);
  };

  return (
    <div className="animate-in fade-in slide-in-from-top-4 duration-300">

      <div className="flex items-end gap-4 mb-6">
        <div className="w-64">
          <label className="block text-sm text-slate-600 mb-1">Tempo da aula</label>
          <select
            className="w-full border border-slate-300 rounded px-3 py-2 text-sm text-slate-700 focus:outline-none focus:border-blue-500"
            value={tempoAula}
            onChange={(e) => setTempoAula(e.target.value)}
          >
            {disponiveisTempos.map((t: string) => (
              <option key={t} value={t}>{t}</option>
            ))}
          </select>
        </div>
        {!isLaunching && (
          <button
            onClick={() => setIsLaunching(true)}
            disabled={disabled}
            className={`bg-[#eef2ff] text-[#0f2851] border border-blue-100 px-6 py-2 rounded text-sm font-semibold hover:bg-[#e0e7ff] transition h-[38px] shadow-sm active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed`}
          >
            Efetuar lan├ºamento
          </button>
        )}
      </div>

      {isLaunching && (
        <div className="space-y-6 animate-in fade-in slide-in-from-top-4 duration-300">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-medium text-slate-800">Alunos</h3>
            <div className="flex items-center gap-4">
              {isLancado && (
                <button
                  onClick={() => !disabled && setShowDeleteFreqModal(true)}
                  disabled={disabled}
                  className="flex items-center gap-2 bg-red-600 text-white px-4 py-2 rounded text-sm font-medium hover:bg-red-700 transition h-[38px] disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <Trash2 className="w-4 h-4" />
                  Excluir frequ├¬ncia
                </button>
              )}
              <div className="flex items-center gap-2 border border-slate-200 rounded-lg px-4 py-2 bg-white">
                <span className="text-sm text-slate-600">Frequ├¬ncia(s) lan├ºada(s):</span>
                <div className="w-6 h-6 rounded-full bg-green-500 flex items-center justify-center text-white">
                  <Check className="w-4 h-4" />
                </div>
              </div>
              <div className="border border-slate-200 rounded-lg px-4 py-2 bg-white flex items-center gap-3">
                <span className="text-sm text-slate-600">Legenda</span>
                <div className="flex items-center gap-2">
                  <span className="flex items-center gap-1 text-xs"><span className="w-4 h-4 rounded-full bg-slate-400"></span> Sem frequ├¬ncia</span>
                  <span className="flex items-center gap-1 text-xs"><span className="w-4 h-4 rounded-full bg-red-500 text-white flex items-center justify-center font-bold text-[10px]">F</span> Falta</span>
                  <span className="flex items-center gap-1 text-xs"><span className="w-4 h-4 rounded-full bg-amber-400 text-white flex items-center justify-center font-bold text-[10px]">FJ</span> Falta Justificada</span>
                  <span className="flex items-center gap-1 text-xs"><span className="w-4 h-4 rounded-full bg-green-500 text-white flex items-center justify-center font-bold text-[10px]">P</span> Presen├ºa</span>
                </div>
              </div>
            </div>
          </div>

          <div className="relative">
            <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              type="text"
              placeholder="Pesquisar"
              className="w-full border border-blue-100 rounded-lg pl-9 pr-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-[#0f2851] bg-white shadow-sm"
            />
          </div>

          <div className="border border-slate-200 rounded-lg overflow-hidden">
            <table className="w-full text-sm text-left">
              <thead className="bg-slate-50 text-slate-600 font-medium border-b border-slate-200">
                <tr>
                  <th className="px-4 py-3 w-16">N┬║</th>
                  <th className="px-4 py-3">Aluno</th>
                  <th className="px-4 py-3 text-center w-32">{tempoAula}</th>
                  <th className="px-4 py-3 text-center w-64">Participa├º├úo</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {studentData.map((aluno, index) => (
                  <tr key={aluno.id} className={index % 2 === 0 ? 'bg-white' : 'bg-slate-50/30'}>
                    <td className="px-4 py-3 text-slate-500 font-bold tabular-nums">{String(index + 1).padStart(2, '0')}</td>
                    <td className="px-4 py-3">
                      <p className="text-sm font-medium text-slate-700">{aluno.nome}</p>
                      <p className="text-[10px] text-slate-400 font-black uppercase tracking-wider mt-1">Matr├¡cula: {aluno.matricula}</p>
                    </td>
                    <td className="px-4 py-3 text-center">
                      <button
                        onClick={() => !disabled && toggleFreq(aluno.id)}
                        disabled={disabled}
                        className={`w-6 h-6 rounded-full text-white flex items-center justify-center font-bold text-[10px] mx-auto transition-colors disabled:cursor-not-allowed
                          ${aluno.freq === 'P' ? 'bg-green-500' :
                            aluno.freq === 'F' ? 'bg-red-500' :
                            aluno.freq === 'FJ' ? 'bg-amber-400' : 'bg-slate-400'}`}
                      >
                        {aluno.freq}
                      </button>
                    </td>
                    <td className="px-4 py-3">
                      <div className={`flex items-center justify-center rounded-lg overflow-hidden border w-fit mx-auto transition-all ${!aluno.freq ? 'opacity-30 grayscale pointer-events-none border-slate-200' : 'border-blue-100 shadow-sm'}`}>
                        <button
                          disabled={disabled || !aluno.freq}
                          onClick={() => togglePart(aluno.id, 'Presencial')}
                          className={`px-4 py-1.5 text-xs font-bold transition-all ${aluno.part === 'Presencial' ? 'bg-[#0f2851] text-white' : 'bg-white text-[#0f2851] hover:bg-[#eef2ff]'}`}
                        >
                          Presencial
                        </button>
                        <button
                          disabled={disabled || !aluno.freq}
                          onClick={() => togglePart(aluno.id, 'Remoto')}
                          className={`px-4 py-1.5 text-xs font-bold transition-all border-l border-blue-100 ${aluno.part === 'Remoto' ? 'bg-[#0f2851] text-white' : 'bg-white text-[#0f2851] hover:bg-[#eef2ff]'}`}
                        >
                          Remoto
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="flex items-center justify-between text-sm text-slate-600">
            <div className="flex items-center gap-2">
              <span>Mostrando de 1 at├® {studentData.length} de {studentData.length} registros</span>
              <div className="flex items-center gap-2 ml-4">
                <span>Mostrar</span>
                <select className="border border-slate-300 rounded px-2 py-1">
                  <option>100</option><option>50</option><option>25</option>
                </select>
                <span>registros</span>
              </div>
            </div>
            <div className="flex items-center border border-slate-200 rounded-lg overflow-hidden">
              <button className="px-3 py-1.5 bg-slate-50 text-slate-400 flex items-center gap-1 hover:bg-slate-100 transition">
                <ArrowLeft className="w-3 h-3" /> Anterior
              </button>
              <button className="px-3 py-1.5 bg-[#0f2851] text-white font-bold">1</button>
              <button className="px-3 py-1.5 bg-slate-50 text-slate-600 flex items-center gap-1 hover:bg-slate-100 transition border-l border-slate-200">
                Seguinte <ArrowLeft className="w-3 h-3 rotate-180" />
              </button>
            </div>
          </div>

          <div className="pt-6">
            {!disabled && (
              <Captcha
                generatedCaptcha={generatedCaptcha}
                captchaInput={captchaInput}
                setCaptchaInput={setCaptchaInput}
                captchaError={captchaError}
                generateNewCaptcha={generateNewCaptcha}
                className="mb-6"
              />
            )}
            <div className="flex items-center gap-3">
              {!disabled && (
                <button
                  onClick={handleConfirm}
                  className="flex items-center gap-2 bg-[#eef2ff] text-[#0f2851] border border-blue-100 px-6 py-2 rounded text-sm font-bold hover:bg-[#e0e7ff] transition shadow-sm active:scale-95"
                >
                  <Check className="w-4 h-4" /> Confirmar
                </button>
              )}
              <button
                onClick={() => setIsLaunching(false)}
                className={`bg-white text-slate-600 border border-slate-200 px-6 py-2 rounded text-sm font-medium hover:bg-slate-50 transition ${disabled ? 'w-full py-3 text-base rounded-xl font-bold bg-slate-50 hover:bg-slate-100' : ''}`}
              >
                Voltar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal Excluir (moved from Frequencia.tsx if we want it fully encapsulated) */}
      {showDeleteFreqModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowDeleteFreqModal(false)} />
          <div className="relative bg-white rounded-xl shadow-xl border border-slate-200 w-full max-w-md mx-4 p-6 animate-in fade-in zoom-in-95 duration-200">
            <div className="flex items-start gap-4">
              <div className="w-10 h-10 rounded-full bg-red-100 flex items-center justify-center flex-shrink-0">
                <Trash2 className="w-5 h-5 text-red-600" />
              </div>
              <div className="flex-1">
                <h3 className="text-base font-semibold text-slate-800 mb-1">Excluir frequ├¬ncia</h3>
                <p className="text-sm text-slate-600">
                  Tem certeza que deseja excluir a frequ├¬ncia lan├ºada para o dia <strong>{selectedDate}</strong>, tempo <strong>{tempoAula}</strong>?
                </p>
                <p className="text-xs text-red-600 mt-2 font-medium">Esta a├º├úo n├úo pode ser desfeita.</p>
              </div>
            </div>
            <div className="flex items-center justify-end gap-3 mt-6">
              <button onClick={() => setShowDeleteFreqModal(false)} className="px-4 py-2 text-sm font-medium text-slate-600 bg-slate-100 hover:bg-slate-200 rounded transition">Cancelar</button>
              <button onClick={handleExcluirFrequencia} className="px-4 py-2 text-sm font-medium text-white bg-red-600 hover:bg-red-700 rounded transition flex items-center gap-2">
                <Trash2 className="w-4 h-4" /> Sim, excluir
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

