import React, { createContext, useContext, useState, useEffect, useRef, ReactNode } from 'react';
import { supabase } from '../lib/supabase';
import LoadingFallback from '../components/common/LoadingFallback';

export type UserRole = 'ADMIN' | 'GESTOR' | 'SECRETARIO' | 'PROFESSOR' | 'ALUNO';

export interface User {
  id: string;
  name: string;
  email: string; // Adicionado campo de e-mail real
  role: UserRole;
  title: string;
  escola_id?: string; // ID da escola vinculada (para GESTOR/SECRETARIO)
}

interface AuthContextType {
  user: User | null;
  loading: boolean;
  logout: () => Promise<void>;             // Logout Real
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  // Ref para evitar closure stale no callback onAuthStateChange
  const userRef = useRef<User | null>(null);
  useEffect(() => { userRef.current = user; }, [user]);

  // Monitora a sess├úo real do Supabase
  useEffect(() => {
    const fetchUserData = async (session: any) => {
      // Se n├úo h├í sess├úo e j├í n├úo temos usu├írio, apenas paramos o loading inicial
      if (!session?.user) {
        if (user) setUser(null);
        setLoading(false);
        return;
      }

      const { user: authUser } = session;
      const metadata = authUser.user_metadata;

      // Seguran├ºa: Prioriza app_metadata (n├úo alter├ível pelo cliente)
      let role: UserRole = (authUser.app_metadata?.role as UserRole);

      // Sempre buscar dados complementares da tabela usuarios (escola_id, cargo fallback)
      let escolaId: string | undefined;
      try {
        const { data: userData, error } = await supabase
          .from('usuarios')
          .select('cargo, escola_id')
          .eq('id', authUser.id)
          .maybeSingle();

        if (!error && userData) {
          if (!role) {
            role = (userData.cargo as UserRole) || 'PROFESSOR';
          }
          escolaId = userData.escola_id || undefined;
        } else if (!role) {
          role = 'PROFESSOR';
        }
      } catch (err: unknown) {
        console.error('[AuthContext] Falha ao buscar dados complementares do usu├írio no DB:', err);
        if (!role) role = 'PROFESSOR';
      }

      setUser({
        id: authUser.id,
        name: metadata?.full_name || authUser.email?.split('@')[0] || 'Usu├írio',
        email: authUser.email || '',
        role: role,
        title: role,
        escola_id: escolaId,
      });
      setLoading(false);
    };

    // Busca a sess├úo assim que inicializa
    supabase.auth.getSession().then(({ data: { session } }) => {
      fetchUserData(session);
    });

    // Escuta TODOS os eventos de sess├úo explicitamente para seguran├ºa
    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      // Evento que encerra a sess├úo ÔÇö limpar estado imediatamente
      if (event === 'SIGNED_OUT') {
        setUser(null);
        setLoading(false);
        return;
      }

      // Se for apenas uma atualiza├º├úo de foco/token e j├í temos o usu├írio, evitar reprocessar tudo
      // a menos que seja um login novo ou mudan├ºa expl├¡cita
      // Usa userRef (sempre atualizado) para evitar closure stale
      if (userRef.current && session?.user?.id === userRef.current.id) {
        if (event !== 'SIGNED_OUT' && event !== 'PASSWORD_RECOVERY') {
          return;
        }
      }

      // Recupera├º├úo de senha ÔÇö n├úo redirecionar, manter sess├úo parcial
      if (event === 'PASSWORD_RECOVERY') {
        setLoading(false);
        return;
      }
      // Login, token refresh e outros ÔÇö recarregar dados do usu├írio
      fetchUserData(session);
    });

    return () => subscription.unsubscribe();
  }, []);


  // LOGOUT ÔÇö Revoga sess├úo no servidor ANTES de limpar o state da UI
  const logout = async () => {
    try {
      await supabase.auth.signOut();
    } finally {
      setUser(null);
    }
  };

  return (
    <AuthContext.Provider value={{ user, loading, logout }}>
      {loading ? <LoadingFallback /> : children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

