            <div>
              <div className="flex items-center gap-3">
                <Building2 className="w-6 h-6 text-white/80" />
                <h1 className="text-2xl font-black text-white tracking-widest uppercase">
                  {escola.nome}
                </h1>
              </div>
              <div className="flex items-center gap-4 mt-1">
                {escola.inep && (
                  <span className="text-blue-100/70 text-sm font-bold">
                    INEP: {escola.inep}
                  </span>
                )}
                {escola.distrito && (
                  <span className="text-blue-100/70 text-sm font-medium">
                    ┬À {escola.distrito}
                  </span>
                )}
              </div>
            </div>
          </div>

          <div className="flex items-center">
            {/* Logo da Escola */}
            {escola.logo_url && (
              <div className="w-24 h-24 bg-white/10 backdrop-blur-md rounded-2xl p-2 border border-white/20 flex items-center justify-center overflow-hidden group hover:bg-white transition-all duration-300 shadow-2xl">
